/**
 * Shared helpers for the Galaxy benchmark / heap / parity / fallback specs
 * (Phase E2.3). Centralises:
 *
 *   - Fixture loading (deterministic JSON generated by
 *     `scripts/gen-graph-fixtures.mjs`).
 *   - `/api/v1/galaxy` route interception — the benchmark measures the
 *     RENDERER, not the backend materializer (which is bounded at 2000
 *     nodes and would be the wrong thing to bench). Playwright's
 *     `page.route()` returns the fixture JSON verbatim.
 *   - Environment capture (`navigator.userAgent`, `hardwareConcurrency`,
 *     `deviceMemory`, WebGL renderer via `WEBGL_debug_renderer_info`,
 *     viewport, machine label).
 *   - Threshold definitions + the soft-assert "record + log + continue"
 *     policy (the dev-bench flag — see `bench/README.md`).
 *
 * Pure TS, no deps beyond Playwright + Node. The fixtures path is resolved
 * relative to this file so the specs work regardless of the cwd Playwright
 * is launched from.
 */
import { readFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import type { Page, TestInfo } from '@playwright/test'
import { expect } from '@playwright/test'

const __dirname = dirname(fileURLToPath(import.meta.url))
const CONSOLE_DIR = resolve(__dirname, '..')
const FIXTURES_DIR = join(CONSOLE_DIR, 'tests', 'fixtures')
const BENCH_DIR = join(CONSOLE_DIR, 'bench')

// Read the Playwright version once at module load (the spec imports this
// module, so the read happens before any test runs). Stamped into the
// environment.json output for traceability across re-benches.
function readPwVersion(): string {
  try {
    const pkg = JSON.parse(readFileSync(join(CONSOLE_DIR, 'package.json'), 'utf8')) as {
      devDependencies?: { '@playwright/test'?: string }
    }
    return pkg.devDependencies?.['@playwright/test'] ?? 'unknown'
  } catch {
    return 'unknown'
  }
}
const PW_VERSION = readPwVersion()

/** On-the-wire `GalaxyPayload` shape — mirrors `src/lib/api.ts`. */
export interface GalaxyFixture {
  lod: 'community_supernodes' | 'visible_nodes' | 'ego_neighborhood'
  max_nodes: number
  node_count: number
  nodes: { id: string; label: string; kind: string; domain: string }[]
  edges: { source: string; target: string; kind: string }[]
}

/**
 * Synchronously load a named fixture from `tests/fixtures/`. The fixtures are
 * small (the 5k graph is ~1.2 MB) and only loaded once per spec file; reading
 * them at require-time keeps the test bodies simple.
 *
 * Throws if the file is missing — the spec can't run without fixtures. The
 * fix is `node scripts/gen-graph-fixtures.mjs`.
 */
export function loadFixture(name: 'graph-1k' | 'graph-5k' | 'graph-20k' | 'graph-triangle'): GalaxyFixture {
  const path = join(FIXTURES_DIR, `${name}.json`)
  return JSON.parse(readFileSync(path, 'utf8')) as GalaxyFixture
}

/**
 * Install a `page.route()` handler that intercepts EVERY `GET /api/v1/galaxy`
 * request and fulfils it with `fixture`. Subsequent / prior calls to other
 * `/api/v1/...` endpoints (auth, search, etc.) pass through unchanged so the
 * real-backend project can still log in + drive the shell.
 *
 * The match pattern is anchored to the path + query so e.g. `/api/v1/galaxy`
 * with `?zoom=close&focus=...` still hits the intercept — we want every galaxy
 * call, regardless of the params the component passes. The fixture returned
 * is the SAME for every call within a test (the benchmark only cares about
 * renderer throughput, not param-dependent payload shape).
 */
export async function interceptGalaxy(page: Page, fixture: GalaxyFixture): Promise<void> {
  await page.route('**/api/v1/galaxy**', (route) => {
    void route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify(fixture),
    })
  })
}

/**
 * Same as `interceptGalaxy` but lets the test supply a different fixture per
 * call (used by the parity test where the same page may switch between
 * fixtures). The callback receives the request URL so it can pick.
 */
export async function interceptGalaxyDynamic(
  page: Page,
  pick: (url: string) => GalaxyFixture,
): Promise<void> {
  await page.route('**/api/v1/galaxy**', (route) => {
    const fixture = pick(route.request().url())
    void route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify(fixture),
    })
  })
}

/**
 * Navigate the logged-in shell to the Entity page, view a seeded subject,
 * toggle the Galaxy sub-view, and wait for the GalaxyGraph component to
 * finish mounting a renderer (signalled by the `.renderer-badge` appearing).
 *
 * The Entity page requires a subject with at least one claim so the
 * `viewMode='galaxy'` button is enabled. The seeded `GULF` subject works;
 * for pure benchmark runs we don't care about the actual table content, we
 * just need a valid mount point that triggers GalaxyGraph. The intercepted
 * `/api/v1/galaxy` route overrides whatever the backend would return.
 *
 * Returns the galaxy-graph section locator for further assertions.
 */
export async function openGalaxyView(
  page: Page,
  opts: { subject?: string } = {},
): Promise<void> {
  const subject = opts.subject ?? 'GULF'
  // Direct hash navigation avoids the Home → nav click dance and is
  // deterministic across runs.
  await page.goto('/#/entity')
  await expect(page.getByRole('heading', { name: 'Entity', level: 1 })).toBeVisible()
  await page.getByLabel('Subject').fill(subject)
  await page.getByRole('button', { name: 'View' }).click()
  // The galaxy toggle is disabled until claims load. Wait for the table to
  // populate (the seed's GULF row appears), then flip into galaxy view.
  await expect(page.locator('table.claims-table')).toContainText(subject)
  await page.getByRole('button', { name: 'Galaxy view' }).click()
  // Galaxy-meta appears once the renderer has data — the renderer-badge
  // appears once the renderer has been chosen (after capability detection).
  await expect(page.locator('.renderer-badge')).toBeVisible()
}

// ── environment capture ────────────────────────────────────────────────────

/**
 * Captured environment snapshot — written to `bench/environment.json` at the
 * start of the benchmark run. Matches `bench/environment.schema.json`.
 */
export interface BenchEnvironment {
  recorded_at: string
  os: string
  browser: string
  playwright_version: string
  gpu: string | null
  cpu_cores: number
  memory_gb: number | null
  viewport: { width: number; height: number }
  device_pixel_ratio: number
  seed: string
  machine_label: string
}

/**
 * Capture the environment from inside the browser. WebGL renderer probe uses
 * `WEBGL_debug_renderer_info` (Chromium exposes it; Firefox gates it behind
 * privacy pref; we accept `null` when blocked). Memory uses
 * `navigator.deviceMemory` (Chromium-only). All other fields are universal.
 *
 * The viewport comes from `page.viewportSize()` (Playwright-controlled, not
 * `window.innerWidth` — which can differ from the configured viewport when
 * the page has scrollbars). `machine_label` defaults to "dev (recorded
 * locally)" but honors the `BENCH_MACHINE_LABEL` env var so a baseline
 * re-bench can tag its outputs.
 */
export async function captureEnvironment(page: Page): Promise<BenchEnvironment> {
  const info = await page.evaluate(() => {
    const ua = navigator.userAgent
    // OS label: prefer navigator.platform (deprecated but still populated in
    // Chromium through at least 2026); fall back to a UA sniff.
    const platform = (navigator as Navigator & { platform?: string }).platform ?? ''
    let os = platform
    if (!os) {
      if (/Windows/i.test(ua)) os = 'Windows'
      else if (/Macintosh|Mac OS X/i.test(ua)) os = 'macOS'
      else if (/Linux/i.test(ua)) os = 'Linux'
      else os = 'unknown'
    }
    const memory = (navigator as Navigator & { deviceMemory?: number }).deviceMemory ?? null
    const cores = navigator.hardwareConcurrency ?? 1

    // WebGL renderer string. Try webgl2 first (3d-force-graph prefers it),
    // fall back to webgl. Both expose WEBGL_debug_renderer_info under the
    // UNMASKED_RENDERER_WEBGL constant.
    let gpu: string | null = null
    try {
      const canvas = document.createElement('canvas')
      const ctx =
        canvas.getContext('webgl2') ??
        canvas.getContext('webgl') ??
        canvas.getContext('experimental-webgl')
      if (ctx) {
        const gl = ctx as WebGLRenderingContext & {
          getExtension?: (name: string) => unknown
          getParameter?: (name: number) => unknown
          DEBUG_RENDERER_INFO?: unknown
        }
        const ext = gl.getExtension?.('WEBGL_debug_renderer_info') as
          | { UNMASKED_RENDERER_WEBGL?: number }
          | undefined
        if (ext && typeof ext.UNMASKED_RENDERER_WEBGL === 'number') {
          const renderer = gl.getParameter?.(ext.UNMASKED_RENDERER_WEBGL)
          if (typeof renderer === 'string') gpu = renderer
        }
        // Explicit loss to free the GL context — the real galaxy graph will
        // create its own.
        const lose = gl.getExtension?.('WEBGL_lose_texture') as
          | { loseContext?: () => void }
          | undefined
        lose?.loseContext?.()
      }
    } catch {
      gpu = null
    }

    return { ua, os, memory, cores, gpu }
  })

  const viewport = page.viewportSize()
  if (!viewport) {
    throw new Error('page.viewportSize() returned null — benchmark requires a fixed viewport')
  }
  const dpr = await page.evaluate(() => window.devicePixelRatio)

  return {
    recorded_at: new Date().toISOString(),
    os: info.os,
    browser: info.ua,
    playwright_version: PW_VERSION,
    gpu: info.gpu,
    cpu_cores: info.cores,
    memory_gb: info.memory,
    viewport: { width: viewport.width, height: viewport.height },
    device_pixel_ratio: dpr,
    seed: 'graph-1k+graph-5k',
    machine_label: process.env.BENCH_MACHINE_LABEL ?? 'dev (recorded locally)',
  }
}

// ── threshold definitions + soft-assert ────────────────────────────────────

/**
 * Phase E2 Task 5.2 DoD thresholds. Calibrated for the baseline hardware
 * (Phase F re-bench). On a dev machine (no GPU + throttled rAF) these are
 * routinely below threshold without indicating a regression — the soft-assert
 * pattern records + logs + continues instead of failing.
 */
export const THRESHOLDS = {
  fps1k: 45,
  fps5k: 30,
  clickP95Ms: 100,
  searchToFocusP95Ms: 300,
  heapGrowthPct: 10,
} as const

/** A single recorded metric with its pass/fail flag. */
export interface BenchMetric {
  name: string
  value: number
  unit: string
  threshold: number
  threshold_met: boolean
  /** Optional human-readable note (e.g. "3D deferred — headless no GPU"). */
  note?: string
}

/**
 * Soft-assert: print a `[BENCH]` log line + return a `BenchMetric`. NEVER
 * throws — the dev-bench policy explicitly accepts below-threshold numbers
 * on dev machines. The caller accumulates metrics + writes them to the
 * results JSON at the end of the run.
 */
export function recordMetric(
  testInfo: TestInfo,
  name: string,
  value: number,
  unit: string,
  threshold: number,
  opts: { lowerIsBetter?: boolean; note?: string } = {},
): BenchMetric {
  const lowerIsBetter = opts.lowerIsBetter ?? false
  const threshold_met = lowerIsBetter ? value <= threshold : value >= threshold
  const flag = threshold_met ? 'OK' : 'BELOW-THRESHOLD (dev-bench accepted)'
  const note = opts.note ? `  note: ${opts.note}` : ''
  // Playwright's TestInfo is annotated so the metric shows up in the JSON
  // reporter too (in addition to stdout).
  testInfo.annotations.push({
    type: `bench:${name}`,
    description: `${value} ${unit} (threshold ${threshold} ${unit}) — ${flag}${note}`,
  })
  // Use console.log directly so the [BENCH] line shows in Playwright's list
  // reporter even when the test passes.
  console.log(
    `[BENCH] ${name}: ${value} ${unit} (threshold ${threshold}) — ${flag}${note}`,
  )
  return { name, value, unit, threshold, threshold_met, note: opts.note }
}

/**
 * Write the environment + results JSON files to `bench/`. Files are gitignored
 * (machine-specific); the writer creates the dir on first run.
 *
 * Uses Node's fs directly (not page.evaluate) since the file lives on the
 * Playwright host, not in the browser.
 */
export async function writeBenchOutputs(
  env: BenchEnvironment,
  metrics: BenchMetric[],
): Promise<void> {
  const { mkdirSync, writeFileSync } = await import('node:fs')
  mkdirSync(BENCH_DIR, { recursive: true })
  writeFileSync(join(BENCH_DIR, 'environment.json'), JSON.stringify(env, null, 2) + '\n', 'utf8')
  const dateTag = new Date().toISOString().slice(0, 10) // YYYY-MM-DD
  const results = {
    recorded_at: env.recorded_at,
    machine_label: env.machine_label,
    environment: env,
    metrics,
  }
  writeFileSync(
    join(BENCH_DIR, `results-dev-${dateTag}.json`),
    JSON.stringify(results, null, 2) + '\n',
    'utf8',
  )
  console.log(`[BENCH] wrote ${join(BENCH_DIR, 'environment.json')} + results-dev-${dateTag}.json`)
}

// ── small stats helpers ────────────────────────────────────────────────────

export function median(xs: number[]): number {
  if (xs.length === 0) return NaN
  const sorted = [...xs].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2
}

export function percentile(xs: number[], p: number): number {
  if (xs.length === 0) return NaN
  const sorted = [...xs].sort((a, b) => a - b)
  // Nearest-rank percentile (p=95 → the ceil(0.95*n)-th element).
  const idx = Math.min(sorted.length - 1, Math.ceil((p / 100) * sorted.length) - 1)
  return sorted[Math.max(0, idx)]
}
